-- ============================================================================
-- Migration: Update marketing mail templates: rename tool_relist to tool_outreach
-- Created At: 2026-10-02
-- Description:
--   Renames the listing outreach template key and id from 'tool_relist' to 'tool_outreach'
--   (Name: 'Tool Outreach') in site_settings.marketing_mail_templates.
--   Replaces {{tool_name}} with {{tool_domain}} in the subject line, HTML title,
--   and email body (where {{tool_domain}} is rendered with a link).
-- ============================================================================

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM site_settings WHERE key = 'marketing_mail_templates') THEN
    UPDATE site_settings
    SET value = (value - 'tool_relist' - 'relist_launch') || jsonb_build_object(
      'tool_outreach',
      $tmpl${
        "id": "tool_outreach",
        "name": "Tool Outreach",
        "description": "Outreach template inviting founders to list their tool on Toolbit.ai",
        "subject": "{{tool_domain}}, let's get you listed on Toolbit.ai",
        "from_name": "Toolbit AI",
        "from_email": "team@mail.toolbit.ai",
        "html": "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Transitional//EN' 'http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd'><html xmlns='http://www.w3.org/1999/xhtml' lang='en'><head><meta http-equiv='Content-Type' content='text/html; charset=UTF-8' /><meta name='viewport' content='width=device-width, initial-scale=1.0' /><meta http-equiv='X-UA-Compatible' content='IE=edge' /><title>{{tool_domain}}, let's get you listed on Toolbit.ai</title><style type='text/css'>@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700;800&display=swap');body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }img { -ms-interpolation-mode: bicubic; border: 0; outline: none; text-decoration: none; }body { height: 100% !important; margin: 0 !important; padding: 0 !important; width: 100% !important; background-color: #f9f8f6; font-family: 'Figtree', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; }p { margin: 0 0 16px 0 !important; line-height: 1.6 !important; color: #3f3f46 !important; font-size: 15px !important; }strong { color: #18181b !important; font-weight: 600 !important; }a { color: #0d9488 !important; text-decoration: underline !important; font-weight: 500 !important; }@media only screen and (max-width: 600px) { .responsive-table { width: 100% !important; } .mobile-padding { padding-left: 20px !important; padding-right: 20px !important; } }</style></head><body style='margin: 0; padding: 0; background-color: #f9f8f6;'><table role='presentation' border='0' cellpadding='0' cellspacing='0' width='100%' style='background-color: #f9f8f6; width: 100%;'><tr><td align='center' style='padding: 32px 16px;'><table role='presentation' border='0' cellpadding='0' cellspacing='0' width='100%' class='responsive-table' style='max-width: 580px; background-color: #ffffff; border-radius: 12px; border: 1px solid #e4e2db; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.03);'><tr><td style='padding: 32px 32px 20px 32px; background-color: #fcfbfa; border-bottom: 1px solid #f4f4f5; text-align: left;' class='mobile-padding'><a href='https://www.toolbit.ai/' target='_blank' style='text-decoration: none; display: inline-block;'><img src='https://www.toolbit.ai/logo-icon.png' alt='Toolbit.ai Logo' width='28' height='28' style='display: inline-block; vertical-align: middle; margin-right: 8px; width: 28px; height: 28px; border: 0;' /><span style='display: inline-block; vertical-align: middle; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 20px; font-weight: 750; letter-spacing: -0.8px; color: #0d9488;'>Toolbit.ai</span></a></td></tr><tr><td style='padding: 32px 32px 24px 32px; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 15px; line-height: 1.6; color: #3f3f46;' class='mobile-padding'><p style='margin: 0 0 16px 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>Hey <strong style='color: #18181b; font-weight: 600;'>{{first_name}}</strong>,</p><p style='margin: 0 0 16px 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>Want more people to find <strong style='color: #18181b; font-weight: 600;'>{{tool_domain}}</strong>? Toolbit.ai is a platform where people discover and compare AI tools, and we'd love to list your tool.</p><p style='margin: 0 0 16px 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>Listing is free (with launch badge verification), and takes just a couple of minutes.</p><p style='margin: 0 0 12px 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>If you want <strong style='color: #18181b; font-weight: 600;'>{{tool_domain}}</strong> to get more benefits and stand out from day one, our Paid Launch Plan includes:</p><div style='margin: 0 0 16px 0;'><div style='margin: 0; line-height: 1.5; font-size: 15px; color: #3f3f46;'><span style='color: #18181b; font-size: 14px; font-weight: 600; margin-right: 8px;'>✓</span>Review within <strong style='color: #18181b; font-weight: 600;'>24 hours</strong> (skip the standard queue)</div><div style='margin: 0; line-height: 1.5; font-size: 15px; color: #3f3f46;'><span style='color: #18181b; font-size: 14px; font-weight: 600; margin-right: 8px;'>✓</span><strong style='color: #18181b; font-weight: 600;'>Featured placement</strong> on the sidebar</div><div style='margin: 0; line-height: 1.5; font-size: 15px; color: #3f3f46;'><span style='color: #18181b; font-size: 14px; font-weight: 600; margin-right: 8px;'>✓</span><strong style='color: #18181b; font-weight: 600;'>Blue Verified Tick</strong> on your listing</div><div style='margin: 0; line-height: 1.5; font-size: 15px; color: #3f3f46;'><span style='color: #18181b; font-size: 14px; font-weight: 600; margin-right: 8px;'>✓</span>Permanent directory placement with a <strong style='color: #18181b; font-weight: 600;'>do-follow backlink</strong></div><div style='margin: 0; line-height: 1.5; font-size: 15px; color: #3f3f46;'><span style='color: #18181b; font-size: 14px; font-weight: 600; margin-right: 8px;'>✓</span>A dedicated <strong style='color: #18181b; font-weight: 600;'>X/Twitter post</strong> featuring your tool</div></div><p style='margin: 0 0 16px 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>👉 <strong style='color: #18181b; font-weight: 600;'>See pricing and submit here:</strong> <a href='https://www.toolbit.ai/submit' target='_blank' style='color: #0d9488; text-decoration: underline; font-weight: 500;'>https://www.toolbit.ai/submit</a></p><p style='margin: 0 0 16px 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>Have something more specific in mind &ndash; a featured ads placement, or a custom listing package? Just reply, happy to work something out.</p><div style='margin: 20px 0 0 0; line-height: 1.6; color: #3f3f46; font-size: 15px;'>Best,<br>Toolbit AI<br><a href='https://www.toolbit.ai/' style='color: #0d9488; text-decoration: underline; font-weight: 500;' target='_blank'>https://www.toolbit.ai/</a></div></td></tr><tr><td align='center' style='padding: 24px 24px 28px 24px; background-color: #fcfbfa; border-top: 1px solid #f4f4f5; text-align: center;' class='mobile-padding'><p style='margin: 0 0 0 0 !important; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 13.5px !important; color: #52525b !important; line-height: 1.4 !important; text-align: center;'>You received this email regarding AI tool discovery and opportunities on Toolbit.ai.</p><p style='margin: 4px 0 12px 0 !important; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 12px !important; color: #a1a1aa !important; line-height: 1.4 !important; text-align: center;'>Feel free to reply this mail or reach out to us at <a href='mailto:contact@toolbit.ai' style='color: #71717a !important; text-decoration: underline !important; font-weight: 500 !important;'>contact@toolbit.ai</a>.</p><div style='margin-bottom: 12px;'><a href='https://www.toolbit.ai/' style='color: #71717a; text-decoration: none; font-weight: 600; font-size: 12px; margin: 0 6px;' target='_blank'>Home</a> &middot; <a href='https://www.toolbit.ai/contact' style='color: #71717a; text-decoration: none; font-weight: 600; font-size: 12px; margin: 0 6px;' target='_blank'>Contact</a></div><p style='margin: 0 !important; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 11px !important; color: #94a3b8 !important; line-height: 1.4 !important; text-align: center;'>&copy; 2026 Toolbit AI. All rights reserved.</p></td></tr></table></td></tr></table></body></html>",
        "text": "Hey **{{first_name}}**,\n\nWant more people to find **{{tool_domain}}**? Toolbit.ai is a platform where people discover and compare AI tools, and we'd love to list your tool.\n\nListing is free (with launch badge verification), and takes just a couple of minutes.\n\nIf you want **{{tool_domain}}** to get more benefits and stand out from day one, our Paid Launch Plan includes:\n\n✓ Review within **24 hours** (skip the standard queue)\n✓ **Featured placement** on the sidebar\n✓ **Blue Verified Tick** on your listing\n✓ Permanent directory placement with a **do-follow backlink**\n✓ A dedicated **X/Twitter post** featuring your tool\n\n👉 See pricing and submit here: https://www.toolbit.ai/submit\n\nHave something more specific in mind – a featured ads placement, or a custom listing package? Just reply, happy to work something out.\n\nBest,\nToolbit AI\nhttps://www.toolbit.ai/",
        "variables": ["{{first_name}}", "{{tool_domain}}"],
        "created_at": "2026-09-26T12:00:00.000Z",
        "updated_at": "2026-10-02T15:45:00.000Z"
      }$tmpl$::jsonb
    )
    WHERE key = 'marketing_mail_templates';
  END IF;

  -- Update historical conversation_history entries so template_id is tool_outreach
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'public' AND table_name = 'marketing_outreach_leads'
  ) THEN
    UPDATE public.marketing_outreach_leads
    SET conversation_history = (
      replace(
        replace(
          conversation_history::text,
          '"template_id": "tool_relist"',
          '"template_id": "tool_outreach"'
        ),
        '"template_id":"tool_relist"',
        '"template_id":"tool_outreach"'
      )
    )::jsonb
    WHERE conversation_history::text LIKE '%"template_id"%tool_relist%';
  END IF;
END $$;
